 const c=g.S17Lesson;let timer=null,busy=false,task=-1,computations=0,lastRun=null;
 const $=id=>document.getElementById(id),safe=s=>String(s??'').replace(/[&<>"']/g,x=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[x]));
